# SaleHop: badges, check-ins, and progressive lead capture
#
# What this adds:
#  1. Fifteen cosmetic badges across four categories -- Scout (spotting
#     sales), Explorer (checking in at sales/ads), Seller (posting sales),
#     Community (helping confirm others' reports) -- tracked anonymously
#     per-device (the same browser/phone id already used for spotted-sale
#     reports), no account required.
#  2. A new "I'm here!" check-in button on a sale's detail sheet and on any
#     physical-location ad's page (Goodwill, ReStore, a recurring flea
#     market) -- geofenced the same way the existing spotted-sale confirm
#     flow is, so it can't be faked from across town.
#  3. A Foursquare-style "Mayor" for physical-location ads: whoever has
#     checked in on the most distinct days is shown right on that ad's
#     page, once they've set a username.
#  4. Progressive lead capture: the first badge someone earns pops a small
#     form asking for an email (required to save that badge to their
#     profile) plus an optional username. Once a device has racked up 3+
#     badges, the next one also asks for a phone number, framed as a real
#     perk (text alerts) -- always skippable, and skipping never loses the
#     badge itself (it's already recorded).
#  5. A new "My Badges" screen (reachable from Account, signed in or not)
#     showing your own badge grid plus a public leaderboard of everyone
#     who's set a username -- email/phone/device id are never shown there,
#     only on the new admin Players section (see #6).
#  6. A new "Players" section in /admin -- the actual payoff of this whole
#     feature: every email/phone captured this way, with badge counts and
#     a CSV export button. Nothing here is ever public.
#
# Includes a new database migration, supabase/schema-v13-badges.sql -- run
# it once in the Supabase SQL Editor (Project -> SQL Editor -> New query ->
# paste the file's contents -> Run) to create the players/player_activity
# tables and turn all of this on. It also fixes a latent bug: the ad
# frequency = 0 ("show every ad") setting from a previous update could
# still be rejected by an old database-level check constraint until this
# migration relaxes it. Everything else in this update works immediately;
# the new API routes and UI simply won't have anything to show yet until
# the migration is run.
#
# Possible follow-up (not built yet, just noted): a real monetary reward
# tier (gift cards, or eventually some kind of points/credit system) once
# SaleHop has an established user base -- badges are cosmetic-only for now
# on purpose.
#
# Touches: app/api/spotted-sales/route.js, app/api/spotted-sales/[id]/
# photos/route.js, components/AppShell.js, components/AccountScreen.js,
# components/ListingSheet.js, components/MapScreen.js, app/ad/[id]/
# page.js, app/admin/page.js. Adds: supabase/schema-v13-badges.sql,
# lib/badges.js, lib/badgeEngine.js, lib/getAdMayor.js,
# app/api/checkins/route.js, app/api/players/me/route.js,
# app/api/players/claim/route.js, app/api/leaderboard/route.js,
# app/api/admin/players/route.js, components/BadgeUnlockModal.js,
# components/BadgesScreen.js, components/CheckInButton.js,
# components/AdCheckIn.js. No new npm package.

if (-not (Test-Path "package.json")) {
    Write-Host "ERROR: package.json not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}
if (-not (Test-Path ".git")) {
    Write-Host "ERROR: .git folder not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}

[System.IO.Directory]::SetCurrentDirectory((Get-Location).Path)


